      "filename": "attempt2.py",
      "content": "import os\r\nimport re\r\nfile_path = os.path.join(os.path.dirname(__file__), 'input.in')\r\nwith open(file_path, 'r') as file:\r\n    content = file.read()\r\nranges = re.split(',|\\n', content)\r\ninvalids = []\r\n\r\ndef get_factors(n):\r\n    factors = set()\r\n    for i in range(1, int(n**0.5) + 1):\r\n        if n % i == 0:\r\n            factors.add(i)\r\n            factors.add(n // i)\r\n    return factors\r\n\r\nfor s in ranges:\r\n    if s == '':\r\n        continue\r\n    head, tail = s.split('-')\r\n    for i in range(int(head), int(tail) + 1):\r\n        strlen = len(str(i))\r\n        factors = get_factors(strlen)\r\n        factors.remove(strlen)\r\n        is_invalid = False\r\n        for factor in factors:\r\n            substr = str(i)[:factor]\r\n            \r\n            if substr * (strlen // factor) == str(i):\r\n                invalids.append(i)\r\n                is_invalid = True\r\n                break\r\n\r\nprint(sum(invalids))\r\n            \r\n        ",
